1	import { Component, computed, effect, inject, input, signal, viewChildren } from '@angular/core';
2	
3	import { SeatMapService } from '../../../core/services/seat-map.service';
4	import { PriceCategory, Seat as SeatModel, SeatMap } from '../../../core/models/seat-map.model';
5	import { Seat } from '../seat/seat';
6	import { PriceCategoryPanel } from '../price-category-panel/price-category-panel';
7	
8	interface GridCell {
9	  type: 'seat' | 'aisle';
10	  seat?: SeatModel;
11	}
12	
13	interface Point {
14	  x: number;
15	  y: number;
16	}
17	
18	const MIN_ZOOM = 0.5;
19	const MAX_ZOOM = 3;
20	const PLACEHOLDER_ROWS = 8;
21	const PLACEHOLDER_COLUMNS = 10;
22	
23	function distance(a: Point, b: Point): number {
24	  return Math.hypot(a.x - b.x, a.y - b.y);
25	}
26	
27	function midpoint(a: Point, b: Point): Point {
28	  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
29	}
30	
31	function clamp(value: number, min: number, max: number): number {
32	  return Math.min(max, Math.max(min, value));
33	}
