35	@Component({
36	  selector: 'app-sitzplan-page',
37	  imports: [Seat, PriceCategoryPanel],
38	  templateUrl: './sitzplan-page.html',
39	  styleUrl: './sitzplan-page.scss'
40	})
41	export class SitzplanPage {
42	  private readonly seatMapService = inject(SeatMapService);
43	
44	  readonly id = input.required<string>();
45	
46	  protected readonly seatMap = signal<SeatMap | null>(null);
47	  protected readonly loadError = signal(false);
48	  protected readonly selectedSeatIds = signal<ReadonlySet<string>>(new Set());
49	  protected readonly focusedSeatId = signal<string | null>(null);
50	  protected readonly assignedCategoryId = signal<ReadonlyMap<string, string>>(new Map());
51	  private readonly panelDismissed = signal(false);
52	  private readonly seatComponents = viewChildren(Seat);
53	
54	  protected readonly priceCategories = computed(() => this.seatMap()?.priceCategories ?? []);
55	
56	  protected readonly panelSeatId = computed<string | null>(() => {
57	    const id = this.focusedSeatId();
58	    if (!id || this.panelDismissed() || this.priceCategories().length <= 1) {
59	      return null;
60	    }
61	    return this.selectedSeatIds().has(id) ? id : null;
62	  });
63	
64	  protected readonly panelSeatRow = computed<string | null>(() => {
65	    const id = this.panelSeatId();
66	    return id ? (this.seatMap()?.seats.find((s) => s.seatId === id)?.row ?? null) : null;
67	  });
68	
69	  protected readonly zoom = signal(1);
70	  protected readonly panX = signal(0);
71	  protected readonly panY = signal(0);
72	
73	  protected readonly transform = computed(() => `translate(${this.panX()}px, ${this.panY()}px) scale(${this.zoom()})`);
74	
75	  protected readonly columnNumbers = computed<number[]>(() => {
76	    const map = this.seatMap();
77	    return map ? Array.from({ length: map.columns }, (_, index) => index + 1) : [];
78	  });
79	
80	  private readonly seatByPosition = computed<Map<string, SeatModel>>(() => {
81	    const seatByPosition = new Map<string, SeatModel>();
82	    for (const seat of this.seatMap()?.seats ?? []) {
83	      seatByPosition.set(`${seat.row}:${seat.column}`, seat);
84	    }
85	    return seatByPosition;
86	  });
87	
88	  protected readonly rowsWithCells = computed<{ row: string; cells: GridCell[] }[]>(() => {
89	    const map = this.seatMap();
90	    if (!map) {
91	      return [];
92	    }
93	
94	    const seatByPosition = this.seatByPosition();
95	    const aisleColumns = new Set(map.aisleColumns);
96	
97	    return map.rows.map((row) => ({
98	      row,
99	      cells: Array.from({ length: map.columns }, (_, index): GridCell => {
100	        const column = index + 1;
101	        if (aisleColumns.has(column)) {
102	          return { type: 'aisle' };
103	        }
104	        const seat = seatByPosition.get(`${row}:${column}`);
105	        return seat ? { type: 'seat', seat } : { type: 'aisle' };
106	      })
107	    }));
108	  });
109	
110	  protected readonly placeholderCells = Array.from({ length: PLACEHOLDER_ROWS * PLACEHOLDER_COLUMNS });
111	  protected readonly placeholderColumns = PLACEHOLDER_COLUMNS;
112	
113	  private readonly activePointers = new Map<number, Point>();
114	  private lastPanPoint: Point | null = null;
115	  private pinchStartDistance: number | null = null;
116	  private pinchStartZoom = 1;
117	  private pinchMidpoint: Point | null = null;
118	
119	  constructor() {
120	    effect((onCleanup) => {
121	      this.seatMap.set(null);
122	      this.loadError.set(false);
123	      this.selectedSeatIds.set(new Set());
124	      this.focusedSeatId.set(null);
125	      this.assignedCategoryId.set(new Map());
126	      this.panelDismissed.set(false);
127	
128	      const subscription = this.seatMapService.getSeatMap(this.id()).subscribe({
129	        next: (seatMap) => {
130	          this.seatMap.set(seatMap);
131	          this.setFocusedSeatId(seatMap.seats.find((s) => s.status === 'Free')?.seatId ?? null);
132	        },
133	        error: () => this.loadError.set(true)
134	      });
135	
136	      onCleanup(() => subscription.unsubscribe());
137	    });
138	  }
139	
140	  private setFocusedSeatId(seatId: string | null): void {
141	    this.focusedSeatId.set(seatId);
142	    this.panelDismissed.set(false);
143	  }
144	
145	  protected onSeatToggled(seatId: string): void {
146	    this.setFocusedSeatId(seatId);
147	    const wasSelected = this.selectedSeatIds().has(seatId);
148	
149	    this.selectedSeatIds.update((current) => {
150	      const next = new Set(current);
151	      if (next.has(seatId)) {
152	        next.delete(seatId);
153	      } else {
154	        next.add(seatId);
155	      }
156	      return next;
157	    });
158	
159	    if (wasSelected) {
160	      this.assignedCategoryId.update((current) => {
161	        const next = new Map(current);
162	        next.delete(seatId);
163	        return next;
164	      });
165	    } else if (this.priceCategories().length === 1) {
166	      const onlyCategoryId = this.priceCategories()[0].id;
167	      this.assignedCategoryId.update((current) => new Map(current).set(seatId, onlyCategoryId));
168	    }
169	  }
170	
171	  protected onCategoryChosen(seatId: string, categoryId: string): void {
172	    this.assignedCategoryId.update((current) => new Map(current).set(seatId, categoryId));
173	  }
174	
175	  protected categoryOf(seatId: string): PriceCategory | undefined {
176	    const categoryId = this.assignedCategoryId().get(seatId);
177	    return categoryId ? this.priceCategories().find((c) => c.id === categoryId) : undefined;
178	  }
179	
180	  protected onGridKeydown(event: KeyboardEvent): void {
181	    if (event.key === 'Escape') {
182	      const seatId = this.panelSeatId();
183	      if (seatId) {
184	        event.preventDefault();
185	        this.panelDismissed.set(true);
186	        const seat = this.seatMap()?.seats.find((s) => s.seatId === seatId);
187	        if (seat) {
188	          this.seatComponents()
189	            .find((s) => s.row() === seat.row && s.column() === seat.column)
190	            ?.focusSeat();
191	        }
192	      }
193	      return;
194	    }
195	
196	    const map = this.seatMap();
197	    const current = map?.seats.find((s) => s.seatId === this.focusedSeatId());
198	    if (!map || !current) {
199	      return;
200	    }
201	
202	    const rowIndex = map.rows.indexOf(current.row);
203	    let nextSeat: SeatModel | undefined;
204	
205	    switch (event.key) {
