/* You can add global styles to this file, and also import other style files */

:root {
  /* Colors */
  --color-surface-base: #FAF7F2;
  --color-surface-raised: #FFFFFF;
  --color-surface-sunken: #EFEAE0;
  --color-ink-primary: #211D18;
  --color-ink-secondary: #6B6255;
  --color-ink-disabled: #B0A99C;
  --color-border-hairline: #E3DDD1;
  --color-accent: #B3542A;
  --color-accent-foreground: #FFFFFF;
  --color-danger: #B3261E;
  --color-danger-foreground: #FFFFFF;
  --color-seat-free-fill: #FFFFFF;
  --color-seat-free-border: #8A8171;
  --color-seat-selected-fill: #B3542A;
  --color-seat-selected-foreground: #FFFFFF;
  --color-seat-occupied-fill: #DDD7C9;
  --color-seat-occupied-foreground: #8A8171;

  /* Typography */
  --font-display: 'Source Serif 4', serif;
  --font-body: 'Inter', sans-serif;
  --font-mono-reference: 'JetBrains Mono', monospace;

  --text-display-size: 32px;
  --text-display-weight: 600;
  --text-display-line-height: 1.2;

  --text-display-sm-size: 22px;
  --text-display-sm-weight: 600;
  --text-display-sm-line-height: 1.25;

  --text-body-size: 16px;
  --text-body-weight: 400;
  --text-body-line-height: 1.5;

  --text-label-size: 14px;
  --text-label-weight: 600;
  --text-label-line-height: 1.3;

  --text-meta-size: 13px;
  --text-meta-weight: 400;
  --text-meta-line-height: 1.4;
  --text-meta-letter-spacing: 0.01em;

  --text-mono-reference-size: 18px;
  --text-mono-reference-weight: 600;
  --text-mono-reference-letter-spacing: 0.04em;

  /* Rounded */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  /* Spacing */
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-3: 12px;
  --spacing-4: 16px;
  --spacing-5: 24px;
  --spacing-6: 32px;
  --spacing-7: 48px;
  --spacing-8: 64px;

  /* Layout */
  --layout-content-max-width: 1120px;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background-color: var(--color-surface-base);
  color: var(--color-ink-primary);
  font-family: var(--font-body);
  font-size: var(--text-body-size);
  font-weight: var(--text-body-weight);
  line-height: var(--text-body-line-height);
}

