35	      { id: 'cat-a', name: 'Kategorie A', price: 32 },
36	      { id: 'cat-b', name: 'Kategorie B', price: 22 }
37	    ]
38	  };
39	
40	  it('shows the placeholder grid before the response arrives', () => {
41	    const fixture = TestBed.createComponent(SitzplanPage);
42	    fixture.componentRef.setInput('id', '1');
43	    fixture.detectChanges();
44	
45	    httpMock.expectOne('/api/events/1/sitzplan');
46	
